import{z as i,x as n,o as l,c as d,q as o,j as E,D as e,d as t,s as B,S as r}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"UB-Mesh：递归 nD 全互连、短距电直连优先","description":"","frontmatter":{"title":"UB-Mesh：递归 nD 全互连、短距电直连优先","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ub-mesh.md","filePath":"llm/ub-mesh.md","lastUpdated":1791063341000}'),h={name:"llm/ub-mesh.md"};function p(A,a,C,P,u,D){const s=n("Mermaid");return l(),d("div",null,[a[2]||(a[2]=o('<h1 id="ub-mesh-递归-nd-全互连、短距电直连优先" tabindex="-1">UB-Mesh：递归 nD 全互连、短距电直连优先 <a class="header-anchor" href="#ub-mesh-递归-nd-全互连、短距电直连优先" aria-label="Permalink to &quot;UB-Mesh：递归 nD 全互连、短距电直连优先&quot;">​</a></h1><div class="epigraph"><p>从板上的一维全互连递归到机柜、柜列与 Pod：能用电直连的跳数就不要改走长距交换与光模块。</p><footer>—— Jiang et al., UB-Mesh: a Hierarchically Localized nD-FullMesh Datacenter Network Architecture, arXiv:2503.20377</footer></div><p><a href="/llm/hccs-to-ub">上一课</a>把 HCCS 钉在节点内一致性（公开形态以 8 卡 Atlas 为主），UB 钉在多柜超节点 Scale-Up；二者不是改名。缺口是 UB 域用什么拓扑：对称 Clos 对所有流量一视同仁，光模块与高基数交换随规模恶化。本课写 <strong>UB-Mesh</strong>：层次化、局部优先的 n 维全互连，短距电直连优先。不重讲四档互连的分工表。CloudMatrix384 的 UB 是这篇拓扑的递归落地，不要把论文里 4D-Pod 的 1024 NPU 直接当成 <a href="/llm/cloudmatrix-384">CloudMatrix 384</a> 的 SKU。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LLM 训练与推理的通信有局部性：张量并行、序列并行往往发生在近邻设备上；数据并行、跨 Pod 同步可以更远、更稀。经典 Clos 对所有流量一视同仁，用大量高基数交换机和光模块提供非阻塞，成本与故障率（光模块数量）随规模恶化。论文把需求写成：高带宽给短距、可接受的带宽给长距、少光模块、高可用。对称 Clos 满足性能，不满足成本与可靠性约束。</p><p>直接全连接所有 NPU 又会让链路数按 \\(O(N^2)\\) 爆炸。需要一种拓扑：在每一层上看起来是全互连（低跳数），层与层之间递归展开，物理上优先用短铜缆，只有层间距离超出电信号范围才上光。这就是 nD-FullMesh 的动机。</p><p><span class="marginnote">数字实例：1024 颗卡两两直连，需要 \\(1024\\times1023/2\\approx52\\) 万条链路，每颗卡要有 1023 个对外端口——没有任何芯片长得出这么多端口。递归 nD-FullMesh 的解法是每一层只对「本维邻居」全连，用几跳低跳数换掉几十万条物理线。</span></p><h3 id="递归全互连在说什么" tabindex="-1">递归全互连在说什么 <a class="header-anchor" href="#递归全互连在说什么" aria-label="Permalink to &quot;递归全互连在说什么&quot;">​</a></h3><p>一维：一块板上相邻 NPU 彼此全连。二维：相邻的一维网再彼此全连，对应机柜内。三维、四维：柜列、楼层内的机柜组。论文把虚拟拓扑映射到物理组织，并在这一代把 <strong>UB-Mesh-Pod 定在 4 维</strong>，4 维以上仍用 Clos，以平衡成本与灵活性。递归的要点是：<strong>每一维都优先直连</strong>，而不是每一维都回到核心交换机。跳数与距离同时被压在「这一维的局部」里。</p><p><span class="marginnote">论文估计短距无源电缆约占全部线缆的 86.7%，相对非过订阅 Clos 可减少约 98% 的高基数交换机与约 93% 的光模块，系统成本效率约 2.04×，可用性叙述中有 7.2% 的相对提升。这些是论文相对其 Clos 基线的评估，用来理解「电直连优先」的方向，不是 CloudMatrix 384 交付清单上的器件计数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>构建顺序与并行对齐。把高频、大带宽的并行维（TP、部分 SP、域内 EP）放在低维全互连上，让多数传输走 0–2 跳。把 DP、跨 Pod 放在高维或 Clos。数据放置与集合通信要拓扑感知：论文为此提出 All-Path Routing（APR）、源路由压缩头、拓扑感知无死锁流控（TFC，公开描述为用很少的虚拟通道做全路径）、以及链故障时的直接通知而非逐跳扩散。</p><p>硬件积木包括专用 NPU / CPU、低基数交换 LRS、高基数交换 HRS、网卡，全部经 UB 互联。LRS 做柜内聚合与 CPU–NPU，降低对昂贵高基数交换的依赖。柜间在电信号可达范围内做直连全互连；论文把「一行四柜、再在列向全连」写成与有源电缆距离相匹配的工程点。超出 4 维的规模，用 Clos 接许多 Pod，而不是强行 5 维全连——那是这一代的显式取舍。</p>',13)),(l(),E(r,null,{default:e(()=>[B(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%221D%EF%BC%9A%E6%9D%BF%E4%B8%8A%E5%85%A8%E4%BA%92%E8%BF%9E%22%5D%20--%3E%20R%5B%222D%EF%BC%9A%E6%9F%9C%E5%86%85%E7%9B%B8%E9%82%BB%201D%20%E5%86%8D%E5%85%A8%E8%BF%9E%22%5D%0A%20%20R%20--%3E%20ROW%5B%22%E6%9B%B4%E9%AB%98%E7%BB%B4%EF%BC%9A%E6%9F%9C%E5%88%97%20%2F%20Pod%22%5D%0A%20%20ROW%20--%3E%20POD%5B%22UB-Mesh-Pod%EF%BC%9A%E8%AE%BA%E6%96%87%E4%B8%AD%E7%9A%84%204D%20%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20POD%20--%3E%7C%22%E5%86%8D%E5%BE%80%E4%B8%8A%22%7C%20CLOS%5B%22Clos%EF%BC%9A%E8%B7%A8%20Pod%20Scale-Out%22%5D%0A%20%20B%20-.-%3E%20%7C%22%E7%9F%AD%E8%B7%9D%E7%94%B5%E7%9B%B4%E8%BF%9E%22%7C%20E%5B%22%E9%93%9C%E7%BC%86%E4%BC%98%E5%85%88%22%5D%0A%20%20ROW%20-.-%3E%20%7C%22%E8%B7%9D%E7%A6%BB%E4%B8%8D%E5%A4%9F%E7%94%B5%22%7C%20O%5B%22%E5%85%89%E6%A8%A1%E5%9D%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<h3 id="与-cloudmatrix-384-的关系" tabindex="-1">与 CloudMatrix 384 的关系 <a class="header-anchor" href="#与-cloudmatrix-384-的关系" aria-label="Permalink to &quot;与 CloudMatrix 384 的关系&quot;">​</a></h3><p>384 超节点是生产 SKU：12 计算柜 + 4 通信柜，L1 板载 + L2 子平面，见 <a href="/llm/ub-l1-l2-planes">七子平面</a>。它体现同一原则——局部全互连、UB 统一、能用电则用电——但物理图是两级交换的无阻塞结构，不是把论文插图里的 64+1 机柜 4D-Mesh 原样贴上。读拓扑时分清：<strong>架构论文的 Pod 设计</strong>与<strong>已交付的 384 卡超节点</strong>。递归二字在 CloudMatrix 文中指 UB 设计延续 UB-Mesh，不指定维数必须等于 4。</p><p>可靠性上，论文描述过 64+1：64 颗常规 NPU 加一颗经 LRS 接入的备份，故障时改走一跳而不把整组降成 7 卡。这是 UB-Mesh-Pod 文中的机制；384 SKU 的备援以产品文档为准，不要把 64+1 抄进 8 卡节点的运维手册。</p><p><span class="marginnote">APR 让流量借闲置的维间路径。集合通信若仍按单环默认映射，会浪费 Mesh 的多路径。HCCL / 通信库需要拓扑感知；把以太网 Clos 的 ring 参数搬过来，等于关掉论文里那套优化。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>短距电直连降低的是单跳距离、功耗和光模块故障率；递归全互连降低的是「本维」的交换跳数。两者合在一起，TP 类流量不必爬 Clos 的叶子–脊–叶子。分层带宽则承认：远维链比近维细，这与 LLM 通信矩阵匹配——近的密、远的稀。代价是拓扑不对称：编程必须知道自己在哪一维，故障绕路会改变跳数（64+1 就是直连改一跳）。Clos 的对称性换的是「任意一对都一样」；Mesh 换的是「大多数对都很近」。</p>',6)),(l(),E(r,null,{default:e(()=>[B(s,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22TP%20%2F%20SP%20%2F%20%E5%9F%9F%E5%86%85%20EP%EF%BC%9A%E9%AB%98%E9%A2%91%E5%A4%A7%E5%9D%97%22%5D%20--%3E%20L%5B%22%E6%94%BE%E4%BD%8E%E7%BB%B4%E5%85%A8%E4%BA%92%E8%BF%9E%20%C2%B7%200%E2%80%932%20%E8%B7%B3%20%C2%B7%20%E8%BF%91%E9%82%BB%E7%9B%B4%E8%BF%9E%22%5D%0A%20%20D%5B%22DP%20%2F%20%E8%B7%A8%20Pod%20%E5%90%8C%E6%AD%A5%EF%BC%9A%E7%A8%80%E7%96%8F%E5%8F%AF%E5%AE%B9%E8%BF%9C%22%5D%20--%3E%20H%5B%22%E6%94%BE%E9%AB%98%E7%BB%B4%E6%88%96%20Clos%20%C2%B7%20%E9%93%BE%E8%BE%83%E7%BB%86%20%C2%B7%20%E8%B7%9D%E7%A6%BB%E6%9B%B4%E8%BF%9C%22%5D%0A%20%20L%20--%3E%20F%5B%22%E8%BF%91%E7%9A%84%E5%AF%86%20%C2%B7%20%E8%BF%9C%E7%9A%84%E7%A8%80%20%C2%B7%20%E4%B8%8E%E9%80%9A%E4%BF%A1%E5%B1%80%E9%83%A8%E6%80%A7%E5%AF%B9%E9%BD%90%22%5D%0A%20%20H%20--%3E%20F%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p><span class="marginnote">直觉类比：Clos 像「所有航班都必须经枢纽机场中转」，任何两个城市之间的待遇一样但都要爬一层；Mesh 像「邻近城市大量直飞，远航线用小机型」——大多数旅程更快，代价是航线图不对称，排班（通信库）必须看着地图排。</span></p><p>相对 Clos 的训练性能，论文称多种 LLM 训练任务相对昂贵 Clos 基线的性能下降在约 7% 以内。这是其实验条件下的结果，用来说明「少光模块不一定把训练打穿」，不能当成你的模型与并行度的保证。</p><h3 id="路由与死锁" tabindex="-1">路由与死锁 <a class="header-anchor" href="#路由与死锁" aria-label="Permalink to &quot;路由与死锁&quot;">​</a></h3><p>Mesh 有环，APR 又允许多跳，流控必须防死锁。TFC 被描述为拓扑感知、用 2 条虚拟通道级的资源做无死锁全路径。源路由把转发指令压进短头，减轻逐跳查大表。这些属于网络系统，框架工程师不必实现，但必须知道：拥塞与故障后的路径集合会变，集合通信的性能不是一条水平线。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用 nD-FullMesh 去替换数据中心南北向以太网。不要在只有 ToR Clos 的机房「用软件模拟 UB-Mesh」。不要把 1024 NPU 的 4D-Pod、384 NPU 的 CloudMatrix、以及未来更高维扩展开成同一个规格表。电直连的距离是物理极限；柜列拉太长就必须上光，原则变成「优先」而不是「禁止光」。</p><p><span class="marginnote">常见误区：初学者容易把「递归」读成「维数想加几层加几层」。每加一维，全连的链路数与布线就再涨一轮，所以这一代论文把 Pod 钉在 4 维、其余规模交给 Clos——递归是设计原则，不是无限扩展的承诺。</span></p><p>成本账：少高基数交换与少光模块是论文主张的系统优势；运维要补上拓扑感知的值班能力。可用性依赖备援与快速重路由，而不是假设铜缆永不坏。</p><p><span class="marginnote">出处：arXiv:2503.20377。CloudMatrix384（arXiv:2506.12708）声明其 UB 为 UB-Mesh 之递归。协议细节当时未完全公开，不在此补。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>UB-Mesh 用递归 nD 全互连做局部高带宽，短距电直连优先，远距才上交换与光。</li><li>这一代论文实现取 4D-Pod，再往上接 Clos；维数是工程折中。</li><li>多数 TP/SP 应对齐到 0–2 跳；集合通信要吃多路径。</li><li>CloudMatrix 384 是该原则的生产递归，物理图按 384 SKU 的 L1/L2，不按 1024-Pod 插图抄。</li><li>相对 Clos 的成本与性能数字属于论文基线，不作通用 SLA。</li><li>出处：UB-Mesh 与 CloudMatrix384 公开论文。</li></ul>',11))])}const F=i(h,[["render",p]]);export{c as __pageData,F as default};
